const params = $input.first().json.query || {};
const challenge = params['hub.challenge'] || '';
const verifyToken = params['hub.verify_token'] || '';
const expectedToken = 'livskin_wa_webhook_2026';

if (verifyToken === expectedToken && challenge) {
  return [{ json: { response: challenge, statusCode: 200 } }];
} else {
  return [{ json: { response: 'forbidden', statusCode: 403 } }];
}

// === wa_parser inline (synced con infra/n8n/lib/wa_parser.js) ===
const DAYS_OF_WEEK = { domingo:0,dom:0,lunes:1,lun:1,martes:2,mar:2,miercoles:3,'miércoles':3,mie:3,'mié':3,mier:3,jueves:4,jue:4,viernes:5,vie:5,sabado:6,'sábado':6,sab:6,'sáb':6 };
const MONTHS = { enero:1,ene:1,febrero:2,feb:2,marzo:3,mar:3,abril:4,abr:4,mayo:5,may:5,junio:6,jun:6,julio:7,jul:7,agosto:8,ago:8,septiembre:9,sep:9,set:9,octubre:10,oct:10,noviembre:11,nov:11,diciembre:12,dic:12 };
const INTENT_PATTERNS = {
  confirm: /^\s*(s[ií]+|ok+|dale|perfecto|confirmo|listo|de\s*acuerdo|me\s*sirve|est[áa]\s*bien|esta\s*perfect|👍|✅)([\s,.!]+(perfecto|listo|claro|excelente|genial|👍|✅))*\s*[.!]*\s*$/i,
  reject: /^\s*(no|no\s*me\s*sirve|no\s*puedo|no\s*podr[ée]|no\s*podemos|❌)\s*[.!]*\s*$/i,
  ask_price: /(cu[áa]nto|precio|costo|cuesta|tarifa|cobr[áa]n|paga[mr]|valor)\b/i,
  ask_human: /(hablar\s+(con(\s+la|\s+el)?|al?)\s+(doctora?|m[eé]dica?|humana?|alguien|persona|ti|ud|usted)|atenderme|que\s+me\s+atienda|llam[aoe]r(me)?|tel[eé]fono|hablar\s+contigo|hablar\s+por\s+telefono)/i,
  ask_info: /(qu[ée]\s+es|c[oó]mo\s+(funciona|es|hace)|info|informaci[oó]n|me\s+puede[sn]?\s+(decir|contar|explicar)|necesito\s+saber)/i,
  greeting: /^\s*(hola|buenas|buen\s*d[ií]a|buenas\s*tardes|buenas\s*noches|saludos|hi|hello)\b/i,
  cancel: /(cancel[aoe]r|anul[aoe]r|ya\s*no\s*quiero|no\s*ir[ée]|no\s*podr[ée]\s*ir)\b/i,
  reschedule: /(reagend[aoe]r|reprogram[aoe]r|cambi[aoe]r\s+(fecha|d[ií]a|hora)|otra\s*fecha|otro\s*d[ií]a)\b/i,
};
function normalize(t){return typeof t==='string'?t.trim().toLowerCase():''}
function stripAccents(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function isoLocalPeru(date){const peru=new Date(date.getTime()-5*3600000);const y=peru.getUTCFullYear();const mo=String(peru.getUTCMonth()+1).padStart(2,'0');const d=String(peru.getUTCDate()).padStart(2,'0');const h=String(peru.getUTCHours()).padStart(2,'0');const mi=String(peru.getUTCMinutes()).padStart(2,'0');return `${y}-${mo}-${d}T${h}:${mi}:00-05:00`}
function nextDayOfWeek(now,targetDow){const peruDate=new Date(now.getTime()-5*3600000);const currentDow=peruDate.getUTCDay();let daysToAdd=(targetDow-currentDow+7)%7;if(daysToAdd===0)daysToAdd=7;peruDate.setUTCDate(peruDate.getUTCDate()+daysToAdd);return new Date(peruDate.getTime()+5*3600000)}
function parseTime(text){const lower=normalize(text);let m=lower.match(/\b(\d{1,2}):(\d{2})\b/);if(m){const h=parseInt(m[1],10);const mi=parseInt(m[2],10);if(h>=0&&h<=23&&mi>=0&&mi<=59)return{hour:h,minute:mi}}m=lower.match(/\b(\d{1,2})\s*(am|pm|hs?|h)\b/);if(m){let h=parseInt(m[1],10);const s=m[2];if(s==='pm'&&h<12)h+=12;if(s==='am'&&h===12)h=0;if(h>=0&&h<=23)return{hour:h,minute:0}}m=lower.match(/\b(\d{1,2})\s*(?:de\s+la\s+)?(ma[nñ]ana|tarde|noche)\b/);if(m){let h=parseInt(m[1],10);const p=stripAccents(m[2]);if(p==='manana'&&h>=1&&h<=11)return{hour:h,minute:0};if(p==='tarde'){if(h>=1&&h<=7)return{hour:h+12,minute:0};if(h===12)return{hour:12,minute:0}}if(p==='noche'){if(h>=7&&h<=11)return{hour:h+12,minute:0};if(h===12)return{hour:0,minute:0}}}return null}
function parseDates(text,now){const found=[];const lower=normalize(text);const lowerNoAccents=stripAccents(lower);if(/\bhoy\b/.test(lowerNoAccents)){const pd=new Date(now.getTime()-5*3600000);const t=parseTime(text)||{hour:10,minute:0};pd.setUTCHours(t.hour,t.minute,0,0);const utc=new Date(pd.getTime()+5*3600000);found.push({iso:isoLocalPeru(utc),raw:'hoy',confidence:0.85})}if(/\bma[nñ]ana\b/.test(lower)&&!/pasado\s+ma[nñ]ana/.test(lower)){const pd=new Date(now.getTime()-5*3600000);pd.setUTCDate(pd.getUTCDate()+1);const t=parseTime(text)||{hour:10,minute:0};pd.setUTCHours(t.hour,t.minute,0,0);const utc=new Date(pd.getTime()+5*3600000);found.push({iso:isoLocalPeru(utc),raw:'mañana',confidence:0.9})}if(/pasado\s+ma[nñ]ana/.test(lower)){const pd=new Date(now.getTime()-5*3600000);pd.setUTCDate(pd.getUTCDate()+2);const t=parseTime(text)||{hour:10,minute:0};pd.setUTCHours(t.hour,t.minute,0,0);const utc=new Date(pd.getTime()+5*3600000);found.push({iso:isoLocalPeru(utc),raw:'pasado mañana',confidence:0.9})}for(const [n,dow] of Object.entries(DAYS_OF_WEEK)){const re=new RegExp(`\\b${stripAccents(n)}\\b`);if(re.test(lowerNoAccents)){const utc0=nextDayOfWeek(now,dow);const pd=new Date(utc0.getTime()-5*3600000);const t=parseTime(text)||{hour:10,minute:0};pd.setUTCHours(t.hour,t.minute,0,0);const utc=new Date(pd.getTime()+5*3600000);found.push({iso:isoLocalPeru(utc),raw:n,confidence:0.85})}}const seen=new Set();return found.filter(f=>{if(seen.has(f.iso))return false;seen.add(f.iso);return true})}
function detectIntent(text){const k=[];let intent='unknown';let conf=0;if(INTENT_PATTERNS.ask_price.test(text)){intent='ask_price';conf=0.9;k.push('precio')}else if(INTENT_PATTERNS.ask_human.test(text)){intent='ask_human';conf=0.9;k.push('humano')}else if(INTENT_PATTERNS.cancel.test(text)){intent='cancel';conf=0.85;k.push('cancelar')}else if(INTENT_PATTERNS.reschedule.test(text)){intent='reschedule';conf=0.85;k.push('reagendar')}else if(INTENT_PATTERNS.confirm.test(text)){intent='confirm';conf=0.95;k.push('confirm')}else if(INTENT_PATTERNS.reject.test(text)){intent='reject';conf=0.9;k.push('reject')}else if(INTENT_PATTERNS.ask_info.test(text)){intent='ask_info';conf=0.7;k.push('info')}else if(INTENT_PATTERNS.greeting.test(text)){intent='greeting';conf=0.8;k.push('saludo')}return{intent,confidence:conf,keywords:k}}
function parseMessage(text){const now=new Date();const ii=detectIntent(text);const dates=parseDates(text,now);let intent=ii.intent;let conf=ii.confidence;if(dates.length>0&&(intent==='unknown'||intent==='greeting'||intent==='ask_info')){intent='propose_date';conf=Math.max(conf,0.75)}return{intent,dates,confidence:conf,keywords_matched:ii.keywords}}

// === Process Meta WhatsApp webhook event ===
const body = $input.first().json.body || {};
const entries = body.entry || [];
const results = [];

for (const entry of entries) {
  for (const change of (entry.changes || [])) {
    const value = change.value || {};
    const messages = value.messages || [];
    for (const msg of messages) {
      const from = msg.from;
      const messageId = msg.id;
      const timestamp = msg.timestamp;
      const type = msg.type;
      let bodyText = '';
      if (type === 'text') bodyText = msg.text?.body || '';
      else if (type === 'button') bodyText = msg.button?.text || '';
      else if (type === 'interactive') bodyText = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';

      const parsed = parseMessage(bodyText);

      results.push({
        from,
        messageId,
        timestamp,
        type,
        body: bodyText,
        intent: parsed.intent,
        confidence: parsed.confidence,
        dates: parsed.dates,
        keywords: parsed.keywords_matched,
      });

      console.log(`[WA-PARSE] from=${from} type=${type} intent=${parsed.intent} conf=${parsed.confidence} dates=${parsed.dates.length} body="${bodyText.substring(0, 100)}"`);
    }
  }
}

return [{ json: { received: true, ts: new Date().toISOString(), parsed_count: results.length, results } }];
